test:
template = {'front': [2, 4], 'back': {'records': [{'count': 6}], 'last': 8}}
result = unflatten([21, 23, 25, 27], template)
assert result == {'front': [21, 23], 'back': {'records': [{'count': 25}], 'last': 27}}
assert template == {'front': [2, 4], 'back': {'records': [{'count': 6}], 'last': 8}}
tuple_result = unflatten([14, 16, 18, 20], (3, [5, 7], {'value': 9}))
assert tuple_result == (14, [16, 18], {'value': 20})
assert isinstance(tuple_result, tuple)

for flat_list, template in [([12, 14], [4, 6, 8]), ([19, 21], {'only': 5}), ([33], {'items': [], 'pair': (), 'mapping': {}})]:
    try:
        unflatten(flat_list, template)
        assert False, 'expected ValueError'
    except ValueError:
        pass
assert unflatten([], {'items': [], 'pair': (), 'mapping': {}}) == {'items': [], 'pair': (), 'mapping': {}}
